            ["menu.story"] = new[] { "A HISTÓRIA", "THE STORY", "LA HISTORIA" },
            ["menu.story_by"] = new[] { "Contada em cordel, como se conta no Nordeste: uma lembrança da casa da vó, no interior da Bahia.", "Told in cordel verse, the way it's told in the Northeast of Brazil: a memory of grandma's house in rural Bahia.", "Contada en cordel, como se cuenta en el Nordeste: un recuerdo de la casa de la abuela, en el interior de Bahía." },
            ["menu.story_done"] = new[] { "Bora brincar!", "Let's play!", "¡A jugar!" },
            ["menu.story_skip"] = new[] { "Pular", "Skip", "Saltar" },
            ["menu.story_tap"] = new[] { "toque para continuar", "tap to continue", "toca para continuar" },
            ["story.1.t"] = new[] { "Peço licença", "Excuse me, dear reader", "Pido licencia" },
            ["story.1.b"] = new[] { "Peço licença ao leitor\npra contar uma lembrança\ndo interior da Bahia,\ndo meu tempo de criança,\nna casa da minha vó,\nque era pura festança.\n\nTinha tio, tinha tia,\nmais menino que um quartel,\nrede armada lá na sala,\nsol rachando lá no céu,\ne na mesa da cozinha\ncuscuz, café e pão com mel.", "With your leave, dear reader,\nI'll tell you a memory\nfrom the countryside of Bahia,\nfrom when I was a child,\nat my grandmother's house,\nwhich was one big party.\n\nUncles, aunts, more kids than a barracks,\na hammock hung in the living room,\nthe sun splitting the sky,\nand on the kitchen table\ncouscous, coffee and bread with honey.", "Pido licencia al lector\npara contar un recuerdo\ndel interior de Bahía,\nde mis tiempos de niño,\nen la casa de mi abuela,\nque era pura fiesta.\n\nHabía tíos, había tías,\nmás niños que en un cuartel,\nuna hamaca colgada en la sala,\nel sol partiendo el cielo,\ny en la mesa de la cocina\ncuscús, café y pan con miel." },
            ["story.2.t"] = new[] { "A boneca da tia Unice", "Aunt Unice's doll", "La muñeca de la tía Unice" },
            ["story.2.b"] = new[] { "No quarto da tia Unice,\na mais velha da família,\nmorava uma tal boneca,\nseu tesouro e maravilha:\nninguém botava a mão nela,\ntia guardava em vigília.\n\nFoi aí que o primo Márcio,\ncom cara de quem apronta,\nchamou toda a meninada\ne falou, de ponta a ponta:\n— Quem pega a boneca e some\nsem que a tia dê de conta?", "In aunt Unice's room,\nthe eldest of the family,\nlived a certain doll,\nher treasure and her wonder:\nnobody laid a hand on it,\nthe aunt watched over it day and night.\n\nThen cousin Márcio,\nwith the face of someone up to no good,\ngathered all the kids and said:\n— Who can grab the doll and vanish\nbefore auntie notices?", "En el cuarto de la tía Unice,\nla mayor de la familia,\nvivía una muñeca,\nsu tesoro y maravilla:\nnadie le ponía la mano encima,\nla tía la cuidaba sin descanso.\n\nFue entonces que el primo Márcio,\ncon cara de estar tramando algo,\nllamó a todos los niños y dijo:\n— ¿Quién agarra la muñeca y desaparece\nsin que la tía se dé cuenta?" },
            ["story.3.t"] = new[] { "A peleja", "The scrap", "La pelea" },
            ["story.3.b"] = new[] { "Foi um tal de cochichar,\num tal de “vai você!”, “não!”,\naté que o mais corajoso\nentrou devagar, então…\ne a boneca, num só pulo,\njá estava em outra mão!\n\nQuando a tia deu por falta,\nsaiu que nem trovoada,\nrevirou cama e lençol,\ncozinha, sala, calçada,\natrás de quem a levou,\ncom a sobrancelha fechada.", "There was whispering and “you go!”, “no, you!”,\nuntil the bravest one\nwalked in, slowly, and then…\nthe doll, in a single leap,\nwas already in other hands!\n\nWhen auntie noticed it was gone,\nshe came out like a thunderstorm,\nturned over beds and sheets,\nkitchen, living room, sidewalk,\nafter whoever took it,\nher eyebrows knitted tight.", "Fue un cuchichear,\nun “¡ve tú!”, “¡no!”,\nhasta que el más valiente\nentró despacito, y entonces…\n¡la muñeca, de un solo salto,\nya estaba en otras manos!\n\nCuando la tía notó la falta,\nsalió como un trueno,\ndio vuelta camas y sábanas,\ncocina, sala, vereda,\ntras quien se la llevó,\ncon el ceño fruncido." },
            ["story.4.t"] = new[] { "Cada um no seu canto", "Everyone in their own corner", "Cada uno en su rincón" },
            ["story.4.b"] = new[] { "Foi primo pra todo canto:\ndebaixo da cama, um,\ndentro do guarda-roupa, outro,\nlá na cozinha, zum-zum,\nsob a mesa, mais um par,\ne no baú… mais algum!\n\nNo esconderijo, quietinho,\nsó se ouvia a gritaria:\nquando a tia pegava um,\nera grito e correria,\ncada um trocava de canto\nrindo de tanta alegria.", "Cousins went everywhere:\none under the bed,\nanother inside the wardrobe,\nsome in the kitchen, buzzing,\na couple under the table,\nand a few more in the chest!\n\nHidden and quiet,\nall you could hear was the shouting:\nwhen auntie caught one,\nthere were screams and a stampede,\nand everyone swapped corners,\nlaughing with joy.", "Los primos se fueron a todos lados:\nuno debajo de la cama,\notro dentro del ropero,\nlos de la cocina, zum-zum,\nun par bajo la mesa,\n¡y otros más en el baúl!\n\nEscondidos, quietitos,\nsolo se oía la gritería:\ncuando la tía atrapaba a uno,\nera grito y carrera,\ny cada cual cambiaba de rincón\nriendo de alegría." },
            ["story.5.t"] = new[] { "Menino, almoçar!", "Kids, lunch is ready!", "¡Niños, a almorzar!" },
            ["story.5.b"] = new[] { "E no fim da brincadeira,\nboneca no seu lugar,\ntia Unice abraçava ela,\ne a casa ia gargalhar\naté a vó, lá da cozinha,\ngritar: — Menino, almoçar!\n\nO tempo passou ligeiro,\ncada qual foi pra um lugar,\nmas a lembrança ficou\nfeito retrato no lar:\na casa da vó, a boneca,\ne a vontade de voltar.\n\nPor isso eu fiz este jogo\npra reviver a jornada:\npega a boneca e se esconde,\nque a tia vem arretada!\nAguenta até que a vovó\nchame pra mesa arrumada!", "At the end of the game,\nthe doll back in its place,\naunt Unice hugging it,\nthe whole house burst out laughing\nuntil grandma, from the kitchen,\nshouted: — Kids, lunch is ready!\n\nTime flew by,\neveryone went their own way,\nbut the memory stayed\nlike a photo on the wall:\ngrandma's house, the doll,\nand the wish to go back.\n\nThat's why I made this game\nto relive the journey:\ngrab the doll and hide,\nbecause auntie is coming, furious!\nHold on until grandma\ncalls everyone to the table!", "Al final del juego,\nla muñeca en su lugar,\nla tía Unice la abrazaba\ny toda la casa reía\nhasta que la abuela, desde la cocina,\ngritaba: — ¡Niños, a almorzar!\n\nEl tiempo pasó volando,\ncada cual siguió su camino,\npero el recuerdo quedó\ncomo un retrato en el hogar:\nla casa de la abuela, la muñeca\ny las ganas de volver.\n\nPor eso hice este juego\npara revivir la jornada:\n¡agarra la muñeca y escóndete,\nque la tía viene furiosa!\n¡Aguanta hasta que la abuela\nte llame a la mesa servida!" },

            // ---------- StoryPicker.cs: choosing the story (= the map) ----------
            ["menu.stories_title"] = new[] { "ESCOLHA A HISTÓRIA", "CHOOSE THE STORY", "ELIGE LA HISTORIA" },
            ["menu.stories_desc"] = new[] { "Cada história acontece em um lugar diferente.", "Each story takes place somewhere different.", "Cada historia ocurre en un lugar distinto." },
            ["stories.doll.name"] = new[] { "A Boneca", "The Doll", "La Muñeca" },
            ["stories.doll.blurb"] = new[] { "Na casa da vó, a boneca da tia Unice sumiu. Esconde, que ela vem!", "At grandma's house, aunt Unice's doll is gone. Hide, she's coming!", "En la casa de la abuela, la muñeca de la tía Unice desapareció. ¡Escóndete, que viene!" },
            ["stories.lobisomem.name"] = new[] { "O Lobisomem", "The Werewolf", "El Hombre Lobo" },
