            // ---------- Ui.cs: "how to play" rules ----------
            ["rule.unice.t"] = new[] { "A Unice", "Unice", "Unice" },
            ["rule.unice.b"] = new[] { "é a velha dona da casa e morre de ciúmes da boneca e das coisas dela. Um jogador vira a Unice e caça quem pegou a boneca.", "is the old lady who owns the house and is insanely jealous of the doll and her things. One player becomes Unice and hunts whoever took the doll.", "es la anciana dueña de la casa y muere de celos por la muñeca y sus cosas. Un jugador se convierte en Unice y caza a quien se llevó la muñeca." },
            ["rule.teamwin.t"] = new[] { "O time vence", "The team wins", "El equipo gana" },
            ["rule.teamwin.b"] = new[] { "se o relógio zerar e a Unice não tiver pegado a boneca de volta.", "if the clock runs out and Unice hasn't gotten the doll back.", "si el reloj llega a cero y Unice no recuperó la muñeca." },
            ["rule.unicewin.t"] = new[] { "A Unice vence", "Unice wins", "Unice gana" },
            ["rule.unicewin.b"] = new[] { "se pegar quem está com a boneca. Pegar outra pessoa só tira ela da rodada.", "if she catches whoever has the doll. Catching someone else just takes them out of the round.", "si atrapa a quien tiene la muñeca. Atrapar a otra persona solo la saca de la ronda." },
