            ["rule.dark.t"] = new[] { "No escuro", "In the dark", "En la oscuridad" },
            ["rule.dark.b"] = new[] { "No esconderijo você enxerga só um pouquinho em volta e ouve o resto: passos, rangidos e risadas.", "Hidden, you can barely see around you and have to listen for the rest: footsteps, creaks and giggles.", "Escondido, apenas ves un poco a tu alrededor y tienes que escuchar el resto: pasos, crujidos y risitas." },
            ["rule.gigglerule.t"] = new[] { "A boneca ri", "The doll giggles", "La muñeca se ríe" },
            ["rule.gigglerule.b"] = new[] { "a cada 10 s escondida e entrega o lugar. Troque de esconderijo ou passe a boneca para alguém bem perto, mesmo escondido.", "every 10s while hidden and gives away the spot. Change hiding spots or pass the doll to someone close by, even while hidden.", "cada 10s mientras está escondida y delata el lugar. Cambia de escondite o pásale la muñeca a alguien cercano, incluso escondido." },
            ["rule.laugh.t"] = new[] { "Qualquer um pode rir", "Anyone can laugh", "Cualquiera puede reírse" },
            ["rule.laugh.b"] = new[] { "o botão Rir entrega sua posição pra Unice igual a risada da boneca, e trava por alguns segundos depois de usado.", "the Laugh button gives away your position to Unice just like the doll's own giggle, and locks for a few seconds after use.", "el botón Reír delata tu posición a Unice igual que la risita de la muñeca, y se bloquea unos segundos después de usarlo." },
